MODEL (
  name silver.order_item,
  kind INCREMENTAL_BY_TIME_RANGE (time_column order_date),
  grain (order_id, line_no),
  partitioned_by (days(order_date)),
  audits (order_item_key_unique, not_null(columns := (order_date)))
);

SELECT
  CAST(index AS BIGINT) AS line_no,
  CAST(TO_UTC_TIMESTAMP(
    CAST(CASE
      WHEN (
        SUBSTRING(CAST(created_at AS STRING), 11) LIKE '%+%'
        OR SUBSTRING(CAST(created_at AS STRING), 11) LIKE '%-%'
      )
      OR UPPER(SUBSTRING(CAST(created_at AS STRING), 11)) LIKE '%Z%'
      THEN NULL
      ELSE REPLACE(REPLACE(CAST(created_at AS STRING), 'T', ' '), 't', ' ')
    END AS TIMESTAMP_NTZ),
    'Europe/Paris'
  ) AS TIMESTAMP_NTZ) AS order_date,
  CAST(order_id AS STRING) AS order_id,
  CAST(qty AS BIGINT) AS quantity,
  CAST(CAST(total AS DECIMAL(38, 9)) / qty AS DECIMAL(12, 4)) AS unit_price,
  CAST(ARRAY() AS ARRAY<STRING>) AS _quality_flags,
  TRUE AS _quality_ok
FROM bronze.shopify__order_lines
